import fastapi

from src.analysis import agent
from src.analysis.models import AnalyzeRequest
from src.analysis.repository import AnalysisError, github_url
from src.interview import loader

router = fastapi.APIRouter()


@router.post("/analyze")
def analyze(request: AnalyzeRequest):
    try:
        github_url(request.repo_url)
    except AnalysisError as exc:
        raise fastapi.HTTPException(status_code=422, detail=str(exc)) from exc
    try:
        return agent.analyze_github(request.repo_url, request.role, request.subdir)
    except AnalysisError as exc:
        raise fastapi.HTTPException(status_code=502, detail=str(exc)) from exc


@router.get("/sessions/{session_id}/questions")
def questions(session_id: str):
    try:
        return agent.load_questions(session_id)
    except (loader.SessionError, FileNotFoundError) as exc:
        raise fastapi.HTTPException(status_code=404, detail=str(exc)) from exc
from pydantic import BaseModel, ConfigDict, Field


class Technology(BaseModel):
    name: str = Field(min_length=1)
    usage: str = Field(min_length=1)
    source_files: list[str] = Field(min_length=1)


class ProjectArea(BaseModel):
    name: str = Field(min_length=1)
    description: str = Field(min_length=1)
    optimization_topics: list[str] = Field(min_length=1)
    source_files: list[str] = Field(min_length=1)


class GeneratedQuestion(BaseModel):
    question: str = Field(min_length=1)
    answer: str = Field(min_length=1)
    context: str = Field(min_length=1)
    source_files: list[str] = Field(min_length=1)


class CodebaseAnalysis(BaseModel):
    summary: str = Field(min_length=1)
    technologies: list[Technology] = Field(min_length=1)
    project_areas: list[ProjectArea] = Field(min_length=1)
    questions: list[GeneratedQuestion] = Field(min_length=3, max_length=3)


class AnalyzeRequest(BaseModel):
    model_config = ConfigDict(str_strip_whitespace=True)
    repo_url: str = Field(min_length=1, max_length=300)
    role: str = Field(default="Software Engineer", min_length=1, max_length=200)
    subdir: str = Field(default="", max_length=300)
# Codebase context extraction agent

Gemini reads the source files, identifies technologies and project areas, and
generates three generalized questions about project experience, optimization,
and trade-offs. Candidates do not need to have read the repository.

The Python code only collects files, calls Gemini once, validates the result,
and saves it. There is no separate manual codebase analysis or vector database.

From the repository root:

```sh
uv venv --python 3.12 .venv
uv pip install --python .venv/bin/python -r requirements.txt
```

Fill in `GEMINI_API_KEY` in the root `.env`. The local `.env` is gitignored and
has `GEMINI_MODEL=gemini-2.5-flash` set. You can change it to another model
available to your API key that supports
[structured output](https://ai.google.dev/gemini-api/docs/generate-content/structured-output).

Analyze the local demo:

```sh
.venv/bin/python -m src.analysis --path demo-proj --role "Backend Engineer"
```

Or shallow-clone a public GitHub repository. Use `--subdir` if the project lives
inside a larger repository:

```sh
.venv/bin/python -m src.analysis \
  --repo-url https://github.com/e-left/SuperhumanResources \
  --subdir demo-proj --role "Backend Engineer"
```

The command prints the session ID and parsed questions. It writes:

```text
data/<session_id>/context.json
data/<session_id>/questions/q1.md
data/<session_id>/questions/q2.md
data/<session_id>/questions/q3.md
```

`context.json` contains the summary, technologies, project areas, optimization
topics, questions, and the file coverage. Each question document contains
`# Question`, `# Answer`, and `# Context`, including source paths. Add the actual
candidate profile as `data/<session_id>/candidate.md` before starting the voice
interview at `/?session=<session_id>`.

The FastAPI app also exposes `POST /analyze` with
`{"repo_url": "https://github.com/owner/repo", "role": "Backend Engineer", "subdir": ""}`
and `GET /sessions/<session_id>/questions`.

Collection skips hidden files/directories (including `.env` and `.git`), obvious
credential filenames, symlinks, vendored/generated files, and lockfiles. It sends
up to 150 supported text files, 80 KB per file, 600 KB total. Budget exclusions
are listed in `context.json`; this is a bounded sample for large repositories.
File filtering is not a general secret scanner: source text is sent to Gemini.
No repository code is executed. Clone and Gemini requests have 60 and 90 second
timeouts respectively; failed Gemini calls are not retried automatically.

Tests run offline with a mocked Gemini response:

```sh
.venv/bin/python -m pytest tests/test_analysis.py
```
"""FastAPI app. Run with: uvicorn src.api.app:app"""

import logging
import pathlib

import dotenv
import fastapi
import gradbot

from src.api import llm_proxy
from src.analysis.routes import router as analysis_router
from src.evaluation import evaluator
from src.interview import loader
from src.interview.session import run_interview
from src.shared.models import Report

ROOT = pathlib.Path(__file__).resolve().parents[2]
dotenv.load_dotenv(ROOT / ".env")

gradbot.init_logging()
# Show the interview's own log lines (tool calls, transcript saved) in the server output.
_handler = logging.StreamHandler()
_handler.setFormatter(logging.Formatter("%(asctime)s %(name)s %(levelname)s %(message)s", "%H:%M:%S"))
logging.getLogger("interview").addHandler(_handler)
logging.getLogger("interview").setLevel(logging.INFO)
app = fastapi.FastAPI(title="SuperhumanResources")
app.include_router(llm_proxy.router)
app.include_router(analysis_router)


@app.websocket("/sessions/{session_id}/interview")
async def interview(websocket: fastapi.WebSocket, session_id: str):
    await run_interview(websocket, session_id)


@app.post("/sessions/{session_id}/evaluate")
def evaluate(session_id: str) -> Report:
    try:
        return evaluator.evaluate(session_id)
    except loader.SessionError as exc:
        raise fastapi.HTTPException(status_code=404, detail=str(exc))
    except evaluator.EvaluationError as exc:
        raise fastapi.HTTPException(status_code=422, detail=str(exc))


@app.get("/sessions/{session_id}/report")
def report(session_id: str) -> Report:
    try:
        found = evaluator.load_report(session_id)
    except loader.SessionError as exc:
        raise fastapi.HTTPException(status_code=404, detail=str(exc))
    if found is None:
        raise fastapi.HTTPException(status_code=404, detail="no report yet")
    return found


# Serves web/index.html at / and Gradbot's audio worklet under /static/js.
gradbot.routes.setup(app, static_dir=ROOT / "web")
# Python 3.12+ (gradbot requirement)
