    <p>Voice only. Use a headset if you can.</p>
    <button id="btn">Start</button>
    <div id="status"></div>
  </main>

  <script src="static/js/opus-encoder.js"></script>
  <script src="static/js/audio-processor.js"></script>
  <script src="static/js/synced-audio-player.js"></script>
  <script>
    const sessionId = new URLSearchParams(location.search).get('session') || 'demo';
    const btn = document.getElementById('btn');
    const statusEl = document.getElementById('status');
    let ws = null, player = null, live = false, finished = false;

    function setStatus(text, isError = false) {
      statusEl.textContent = text;
      statusEl.className = isError ? 'error' : '';
    }

    function showReportLink() {
      // The transcript is already saved when this event arrives; the report page runs the evaluation.
      const link = document.createElement('a');
      link.href = `static/report.html?session=${encodeURIComponent(sessionId)}&run=1`;
      link.textContent = 'Evaluate and view report';
      statusEl.append(document.createElement('br'), link);
    }

    function teardown() {
      live = false;
      if (player) { player.stop(); player = null; }
      ws = null;
      btn.classList.remove('live');
      btn.textContent = 'Start';
      btn.disabled = false;
    }

    async function start() {
      finished = false;
      player = new SyncedAudioPlayer({
        basePath: 'static/js',
        sampleRate: 24000,
        echoCancellation: true,
        onEncodedAudio: (data) => {
          if (live && ws && ws.readyState === WebSocket.OPEN) ws.send(data);
        },
        onEvent: (type, msg) => {
          if (type === 'interview_finished') {
            finished = true;
            live = false;  // stop sending mic audio; let the goodbye play out
            setStatus(msg.completed ? 'Interview finished. Thank you.' : 'Interview ended.');
            showReportLink();
          }
        },
        onError: (error) => setStatus(error.message, true),
      });

      try {
        await player.start();
      } catch (error) {
        setStatus('Microphone access denied', true);
        player = null;
        return;
      }

      const protocol = location.protocol === 'https:' ? 'wss:' : 'ws:';
      ws = new WebSocket(`${protocol}//${location.host}/sessions/${sessionId}/interview`);
      ws.onopen = () => {
        ws.send(JSON.stringify({ type: 'start' }));
        live = true;
        btn.classList.add('live');
        btn.textContent = 'End';
        setStatus('Interview in progress');
      };
      ws.onmessage = (event) => player && player.handleMessage(event.data);
      ws.onerror = () => setStatus('Connection error', true);
      ws.onclose = () => {
        if (!finished && statusEl.className !== 'error') setStatus('Disconnected');
        teardown();
      };
    }

    function stop() {
      if (ws && ws.readyState === WebSocket.OPEN) ws.send(JSON.stringify({ type: 'stop' }));
      live = false;
      btn.disabled = true;
      setStatus('Ending…');
    }

    btn.addEventListener('click', () => (ws ? stop() : start()));
  </script>
</body>
