  $('role').setCustomValidity('');
  $('form-error').hidden = true;
  $('repo-url').focus();
});

const sampleContext = {
  session_id: 'sample', repo_url: 'https://github.com/e-left/SuperhumanResources', subdir: 'demo-proj', role: 'Backend Engineer',
  summary: 'FlatPal brings a shared household into one place: expenses, chores, shopping, and the conversations around them. A TypeScript API and relational data model connect a web client and a mobile experience.',
  included_files: ['api/package.json', 'api/prisma/schema.prisma', 'package.json', 'mobile/package.json'], omitted_files: [],
  technologies: [
    { name: 'TypeScript', usage: 'A shared language across the API and client applications.', source_files: ['api/package.json', 'package.json'] },
    { name: 'Prisma', usage: 'Relational models for households and shared responsibilities.', source_files: ['api/prisma/schema.prisma'] },
    { name: 'React Native', usage: 'Mobile access to the household workspace.', source_files: ['mobile/package.json'] },
  ],
  project_areas: [
    { name: 'Shared household data', description: 'Connected members, expenses, and household resources need clear ownership and consistent updates.', optimization_topics: ['Prevent duplicate writes with idempotent operations', 'Enforce household access at the API boundary'], source_files: ['api/prisma/schema.prisma'] },
    { name: 'API and client coordination', description: 'Web and mobile clients share a backend while working with different connectivity and interaction patterns.', optimization_topics: ['Keep client and API contracts compatible', 'Handle failed requests without losing user changes'], source_files: ['api/package.json', 'mobile/package.json'] },
  ],
  questions: [
    { question: 'How would you design an expense-sharing feature so retries cannot create duplicate charges or records?', answer: 'Define an idempotency key for each logical operation, enforce uniqueness in storage, and commit the expense and its allocations atomically. Return the prior result for safe retries and test concurrent submissions.', context: 'Illustrative question inspired by a shared household application and its relational data model.', source_files: ['api/prisma/schema.prisma'] },
    { question: 'How would you make sure a member can only read and change data belonging to their household?', answer: 'Authenticate the caller and check household membership for each operation at the API boundary. Scope reads and writes to an authorized household and test cross-household access attempts.', context: 'Illustrative access-control discussion for an API serving multiple households.', source_files: ['api/prisma/schema.prisma', 'api/package.json'] },
    { question: 'How would you evolve an API used by both web and mobile clients without breaking older app versions?', answer: 'Prefer additive changes, preserve existing field meanings, and use contract tests. Observe client versions before removing old behavior, and roll out incompatible changes through an explicit versioning plan.', context: 'Illustrative compatibility discussion for a backend shared by independently released clients.', source_files: ['api/package.json', 'mobile/package.json'] },
  ],
};

$('preview-button').addEventListener('click', () => {
  $('form-error').hidden = true;
  render(sampleContext, true);
  remember('sample', '1');
  $('output-section').scrollIntoView({ behavior: matchMedia('(prefers-reduced-motion: reduce)').matches ? 'instant' : 'smooth' });
});

for (const tab of document.querySelectorAll('[role="tab"]')) {
  tab.addEventListener('click', () => selectTab(tab.dataset.tab));
  tab.addEventListener('keydown', (event) => {
    const tabs = [...document.querySelectorAll('[role="tab"]')];
    const current = tabs.indexOf(tab);
    let next;
    if (event.key === 'ArrowRight') next = (current + 1) % tabs.length;
    if (event.key === 'ArrowLeft') next = (current - 1 + tabs.length) % tabs.length;
    if (event.key === 'Home') next = 0;
    if (event.key === 'End') next = tabs.length - 1;
    if (next !== undefined) { event.preventDefault(); selectTab(tabs[next].dataset.tab, true); }
  });
}

$('copy-button').addEventListener('click', async () => {
  if (!context || sample) return;
  try {
    await navigator.clipboard.writeText(context.session_id);
    $('copy-button').replaceChildren(icon('check'), document.createTextNode('Session copied'));
    setTimeout(() => $('copy-button').replaceChildren(icon('copy'), document.createTextNode('Copy session')), 2000);
  } catch {
    $('form-error').textContent = `Clipboard unavailable. Session ID: ${context.session_id}`;
    $('form-error').hidden = false;
  }
});

$('download-button').addEventListener('click', () => {
  if (!context) return;
  const url = URL.createObjectURL(new Blob([JSON.stringify(context, null, 2) + '\n'], { type: 'application/json' }));
  const link = el('a');
  link.href = url;
  link.download = sample ? 'sample-context.json' : `context-${context.session_id}.json`;
  document.body.append(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
});

async function restore() {
  const params = new URLSearchParams(location.search);
  const sessionId = params.get('context');
  if (params.get('sample') === '1') { render(sampleContext, true); return; }
  if (!sessionId) return;
  if (!/^[a-f0-9]{32}$/.test(sessionId)) { showError(new Error('This context link contains an invalid session ID. Generate a new analysis.')); return; }
  setBusy(true);
  setAgent('running', 'Reconnecting your context.', 'Loading the saved analysis for this session.', 'Retrieving saved codebase context.');
  try {
    const data = validateContext(await request(`/sessions/${encodeURIComponent(sessionId)}/context`), sessionId);
    $('repo-url').value = data.repo_url;
    $('role').value = data.role;
    $('subdir').value = data.subdir || '';
    render(data);
  } catch (error) { showError(error); }
  finally { setBusy(false); }
}
restore();
